1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync, validateWorkflow } from '../src/engine.js';
4	
5	const workflow = {
6	  id: 'routing',
7	  entry: 'start',
8	  nodes: [
9	    { id: 'start', type: 'trigger', next: 'check' },
10	    { id: 'check', type: 'condition', condition: { field: 'score', operator: 'gte', value: 80 }, then: 'pass', else: 'fail' },
11	    { id: 'pass', type: 'end', result: 'passed' },
12	    { id: 'fail', type: 'end', result: 'failed' }
13	  ]
14	};
15	
16	test('routes a workflow through the matching branch', () => {
17	  assert.equal(executeWorkflow(workflow, { score: 90 }).result, 'passed');
18	  assert.equal(executeWorkflow(workflow, { score: 60 }).result, 'failed');
19	});
20	
21	test('rejects unknown destinations', () => {
22	  const broken = structuredClone(workflow);
23	  broken.nodes[0].next = 'missing';
24	  assert.throws(() => validateWorkflow(broken), /unknown destination/);
25	});
26	
27	function formWorkflow(fields, { formProps = {} } = {}) {
28	  return {
29	    id: 'forms',
30	    entry: 'start',
31	    nodes: [
32	      { id: 'start', type: 'trigger', next: 'collect' },
33	      { id: 'collect', type: 'form', ...(fields ? { schema: { fields } } : {}), ...formProps, next: 'done' },
34	      { id: 'done', type: 'end', result: 'collected' }
35	    ]
36	  };
37	}
38	
39	test('forms without a schema keep the legacy passthrough behavior', () => {
40	  const execution = executeWorkflow(formWorkflow(null), { anything: 1 });
41	  assert.equal(execution.status, 'completed');
42	  assert.deepEqual(execution.context.input, { anything: 1 });
43	});
44	
45	test('applies defaults, preserves undeclared fields, and never mutates the caller input', () => {
46	  const caller = { name: 'Ada', count: 2, untouched: true };
47	  const execution = executeWorkflow(formWorkflow([
48	    { path: 'name', type: 'string' },
49	    { path: 'address.city', type: 'string', default: 'Berlin' },
50	    { path: 'active', type: 'boolean', default: false },
51	    { path: 'count', type: 'integer', default: 0 },
52	  ]), caller);
53	  assert.equal(execution.status, 'completed');
54	  assert.deepEqual(execution.context.input, {
55	    name: 'Ada', count: 2, untouched: true,
