import { executeWorkflowAsync } from './src/engine.js';
const sleep = ms => new Promise(r => setTimeout(r, ms));

// start forks to [finish(end), work(action)]; finish declared first runs first.
function wf() {
  return {
    id: 'early-end', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: ['finish', 'work'] },
      { id: 'finish', type: 'end', result: { verdict: 'approved', items: [{ id: 1 }] } },
      { id: 'work', type: 'action', operation: 'slow', next: 'finish' },
    ],
  };
}

// A) other branch succeeds: recorded end result survives mid-run definition tampering
{
  const w = wf();
  const res = await executeWorkflowAsync(w, {}, {
    slow: async () => {
      await sleep(10);
      // external tampering with the definition's result object during the wait
      w.nodes[1].result.verdict = 'TAMPERED';
      w.nodes[1].result.items.push({ id: 99 });
      return 'done';
    },
  });
  console.log('A status:', res.status);
  console.log('A result:', JSON.stringify(res.result));
  console.log('A def now:', JSON.stringify(w.nodes[1].result));
}

// B) other branch fails: action_failed, no success result
{
  const w = wf();
  const res = await executeWorkflowAsync(w, {}, { slow: () => { throw new Error('boom'); } });
  console.log('B status:', res.status, '| has result:', 'result' in res, '| nodeId:', res.nodeId);
}

// C) cancelled during the wait: cancelled, no success result
{
  const w = wf();
  const ac = new AbortController();
  const res = await executeWorkflowAsync(w, {}, {
    slow: async () => { setTimeout(() => ac.abort(), 10); await sleep(30); return 'done'; },
  }, { signal: ac.signal });
  console.log('C status:', res.status, '| has result:', 'result' in res, '| trace:', res.trace.map(n=>n.nodeId).join(','));
}

// D) two independent async runs of the same definition don't share results
{
  const w = wf();
  const r1 = await executeWorkflowAsync(w, {}, { slow: async () => { await sleep(1); return 1; } });
  const r2 = await executeWorkflowAsync(w, {}, { slow: async () => { await sleep(1); return 2; } });
  r1.result.items[0].id = 111;
  r1.result.verdict = 'one';
  console.log('D r2 untouched:', JSON.stringify(r2.result));
}
"

